-- Pandora Lunar share profiles: fix for the Supabase advisor warning
-- "Function Search Path Mutable" on public.normalize_share_code.
-- Target: Lunar project (ref dehuwlbcfejuiijbpaao).
-- Status: APPLIED on 19 Nov 2026 (UTC). Do not edit this file.
--
-- An empty search_path stops the function from finding objects that a caller
-- puts in another schema. The body uses only upper, regexp_replace and
-- coalesce. These are in pg_catalog, which Postgres always searches, so the
-- result does not change.

alter function public.normalize_share_code(text) set search_path = '';
